arguments.new_str:
namespace Warehouse;

public sealed class InventoryTracker
{
    private readonly Dictionary<string, int> _stock = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, int> _reorderThresholds = new(StringComparer.OrdinalIgnoreCase);

    public int GetStockLevel(string sku)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        return _stock.TryGetValue(sku, out var level) ? level : 0;
    }

    public void AddStock(string sku, int quantity)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(quantity);

        _stock[sku] = GetStockLevel(sku) + quantity;
    }

    public void RemoveStock(string sku, int quantity)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentOutOfRangeException.ThrowIfNegativeOrZero(quantity);

        var current = GetStockLevel(sku);
        if (quantity > current)
            throw new InvalidOperationException(
                $"Cannot remove {quantity} units of '{sku}'. Only {current} in stock.");

        _stock[sku] = current - quantity;
    }

    public void SetReorderThreshold(string sku, int threshold)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);
        ArgumentOutOfRangeException.ThrowIfNegative(threshold);

        _reorderThresholds[sku] = threshold;
    }

    public bool NeedsReorder(string sku)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(sku);

        if (!_reorderThresholds.TryGetValue(sku, out var threshold))
            return false;

        return GetStockLevel(sku) <= threshold;
    }

    /// <summary>
    /// Transfers stock from this warehouse to <paramref name="destination"/>.
    /// </summary>
    public void TransferTo(InventoryTracker destination, string sku, int quantity)
    {
        ArgumentNullException.ThrowIfNull(destination);
        if (ReferenceEquals(this, destination))
            throw new InvalidOperationException("Cannot transfer to the same warehouse.");

        RemoveStock(sku, quantity);
        destination.AddStock(sku, quantity);
    }
}

