using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public sealed class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    // ── Stock Level ──────────────────────────────────────────────

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("UNKNOWN-001"));
    }

    [TestMethod]
    public void AddStock_NewSku_SetsLevel()
    {
        _tracker.AddStock("SKU-A", 10);
        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void AddStock_ExistingSku_AccumulatesQuantity()
    {
        _tracker.AddStock("SKU-A", 5);
        _tracker.AddStock("SKU-A", 7);
        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void AddStock_IsCaseInsensitive()
    {
        _tracker.AddStock("sku-a", 3);
        Assert.AreEqual(3, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddStock_ZeroOrNegativeQuantity_Throws(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-A", qty));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddStock_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.AddStock(sku!, 1));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void GetStockLevel_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.GetStockLevel(sku!));
    }

    // ── Remove Stock ─────────────────────────────────────────────

    [TestMethod]
    public void RemoveStock_SufficientStock_DecreasesLevel()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.RemoveStock("SKU-A", 4);
        Assert.AreEqual(6, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_ExactAmount_LeavesZero()
    {
        _tracker.AddStock("SKU-A", 5);
        _tracker.RemoveStock("SKU-A", 5);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void RemoveStock_InsufficientStock_Throws()
    {
        _tracker.AddStock("SKU-A", 3);
        var ex = Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-A", 10));
        StringAssert.Contains(ex.Message, "SKU-A");
    }

    [TestMethod]
    public void RemoveStock_UnknownSku_Throws()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("NOPE", 1));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-5)]
    public void RemoveStock_ZeroOrNegativeQuantity_Throws(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.RemoveStock("SKU-A", qty));
    }

    // ── Reorder Alerts ───────────────────────────────────────────

    [TestMethod]
    public void NeedsReorder_NoThresholdSet_ReturnsFalse()
    {
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.AddStock("SKU-A", 20);
        _tracker.SetReorderThreshold("SKU-A", 10);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", 10);
        _tracker.SetReorderThreshold("SKU-A", 10);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.AddStock("SKU-A", 3);
        _tracker.SetReorderThreshold("SKU-A", 10);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_ZeroStockWithThreshold_ReturnsTrue()
    {
        _tracker.SetReorderThreshold("SKU-A", 5);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void SetReorderThreshold_NegativeThreshold_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.SetReorderThreshold("SKU-A", -1));
    }

    [TestMethod]
    public void NeedsReorder_ThresholdZeroAndNoStock_ReturnsTrue()
    {
        _tracker.SetReorderThreshold("SKU-A", 0);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    public void NeedsReorder_ThresholdZeroAndHasStock_ReturnsFalse()
    {
        _tracker.AddStock("SKU-A", 1);
        _tracker.SetReorderThreshold("SKU-A", 0);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public void NeedsReorder_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.NeedsReorder(sku!));
    }

    // ── Warehouse Transfers ──────────────────────────────────────

    [TestMethod]
    public void TransferTo_MovesStockBetweenWarehouses()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-A", 20);

        _tracker.TransferTo(destination, "SKU-A", 8);

        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(8, destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_EntireStock_LeavesSourceAtZero()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-A", 5);

        _tracker.TransferTo(destination, "SKU-A", 5);

        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(5, destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_InsufficientStock_ThrowsAndNoSideEffects()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-A", 3);

        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferTo(destination, "SKU-A", 10));

        // Both warehouses should remain unchanged
        Assert.AreEqual(3, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(0, destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_DestinationAlreadyHasStock_Accumulates()
    {
        var destination = new InventoryTracker();
        destination.AddStock("SKU-A", 10);
        _tracker.AddStock("SKU-A", 20);

        _tracker.TransferTo(destination, "SKU-A", 5);

        Assert.AreEqual(15, _tracker.GetStockLevel("SKU-A"));
        Assert.AreEqual(15, destination.GetStockLevel("SKU-A"));
    }

    [TestMethod]
    public void TransferTo_NullDestination_Throws()
    {
        Assert.ThrowsException<ArgumentNullException>(
            () => _tracker.TransferTo(null!, "SKU-A", 1));
    }

    [TestMethod]
    public void TransferTo_SameWarehouse_Throws()
    {
        _tracker.AddStock("SKU-A", 10);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferTo(_tracker, "SKU-A", 5));
    }

    [TestMethod]
    public void TransferTo_TriggersReorderOnSource()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-A", 15);
        _tracker.SetReorderThreshold("SKU-A", 10);

        Assert.IsFalse(_tracker.NeedsReorder("SKU-A"));

        _tracker.TransferTo(destination, "SKU-A", 10);

        Assert.IsTrue(_tracker.NeedsReorder("SKU-A"));
    }
}

